function validate([sentence, searchWord]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 100) return 'sentence needs 1 to 100 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(sentence)) return 'sentence is lowercase words separated by single spaces.';
  if (typeof searchWord !== 'string' || !/^[a-z]{1,10}$/.test(searchWord)) return 'searchWord is 1 to 10 lowercase letters.';
  return null;
}

