function isPrefixOfWord(sentence, searchWord) {
  const words = sentence.split(' ');
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length < searchWord.length) {
      continue;
    }
    let k = 0;
    while (k < searchWord.length && word[k] === searchWord[k]) {
      k++;
    }
    if (k === searchWord.length) {
      return i + 1;
    }
  }
  return -1;
}

