function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = rand() < 0.5 ? 'ab' : 'abc';
  const word = (lo, hi) => Array.from({ length: pick(lo, hi) }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const words = [];
  if (size === 'small') {
    const count = pick(1, 6);
    for (let i = 0; i < count; i++) words.push(word(1, 4));
  } else {
    let length = -1;
    for (;;) {
      const next = word(1, 10);
      if (length + 1 + next.length > 100) break;
      words.push(next);
      length += 1 + next.length;
    }
  }
  let searchWord;
  if (rand() < 0.6) {
    const source = words[Math.floor(rand() * words.length)];
    searchWord = source.slice(0, pick(1, Math.min(10, source.length)));
    if (rand() < 0.3 && searchWord.length < 10) searchWord += letters[Math.floor(rand() * letters.length)];
  } else {
    searchWord = word(1, size === 'small' ? 3 : 10);
  }
  return [words.join(' '), searchWord];
}
